String _read(String path) => File(path).readAsStringSync();

String _between(String text, String from, String to) {
  final a = text.indexOf(from);
  final b = text.indexOf(to, a + from.length);
  expect(a, isNonNegative, reason: 'anchor "$from" not found');
  expect(b, isNonNegative, reason: 'anchor "$to" not found');
  return text.substring(a, b);
}

/// The screenshots harness's font loading (test/screenshots_test.dart):
/// real Roboto + Material Icons from the SDK artifact, so the
/// captures and measurements carry real phone metrics.
Future<void> _loadRealFonts() async {
  Future<void> load(String family, List<String> files) async {
    if (!files.every((f) => File(f).existsSync())) return;
    final loader = FontLoader(family);
    for (final f in files) {
      final bytes = await File(f).readAsBytes();
      loader.addFont(
        Future.value(ByteData.view(Uint8List.fromList(bytes).buffer)),
      );
    }
    await loader.load();
  }

  const dir =
      '/home/hatch/workspace/ember-app/toolchain/flutter/bin/cache/artifacts/material_fonts';
  await load('Roboto', [
    '$dir/Roboto-Regular.ttf',
    '$dir/Roboto-Medium.ttf',
    '$dir/Roboto-Bold.ttf',
    '$dir/Roboto-Italic.ttf',
    '$dir/Roboto-BoldItalic.ttf',
  ]);
  await load('MaterialIcons', ['$dir/MaterialIcons-Regular.otf']);
}

/// Pumps the full shell exactly as the screenshots harness's
/// Mozilla shot does (dead-quiet channels, FakeApi core), on a
/// [width]x[height] logical surface at 2x.
Future<CoreController> _pumpShell(
  WidgetTester tester,
  double width,
  double height,
) async {
  wt.stillMotion(tester);
  tester.view.physicalSize = Size(width * 2, height * 2);
  tester.view.devicePixelRatio = 2;
  addTearDown(tester.view.reset);
  final messenger =
      TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger;
  messenger.setMockMethodCallHandler(const MethodChannel('app/android'), (
    call,
  ) async {
    if (call.method == 'xrayState') {
      return <String, Object?>{
        'running': false,
        'name': '',
        'sinceMs': 0,
        'up': 0,
        'down': 0,
        'coreRestarts': 0,
        'coreProblem': '',
        'chainUnderlay': false,
        'chainProblem': '',
        'awg': false,
        'awgConfig': '',
        'rotationGen': 0,
      };
    }
    return null;
  });
  addTearDown(
    () => messenger.setMockMethodCallHandler(
      const MethodChannel('app/android'),
      null,
    ),
  );
  final core = CoreController(
    () async => wt.FakeApi(),
    pollInterval: const Duration(hours: 1),
  );
  await tester.pumpWidget(VpnApp(core: core, settings: AppSettings()));
  core.start();
  await tester.pump();
  await tester.pump(const Duration(milliseconds: 400));
  await tester.runAsync(
    () => Future<void>.delayed(const Duration(milliseconds: 600)),
  );
  await tester.pump();
  await tester.pump(const Duration(milliseconds: 400));
  return core;
}

/// The acceptance assertions for one surface size.
///
/// PIN UPDATED by the R1 home-fidelity round (2026-11-23,
/// owner order: the whole appearance rebuilt 0–100 to the
/// approved pro3/pro5 samples): on the Home tab the brand
/// panel and the corner rail are GONE — both still serve the
/// other tabs unchanged. The Home header is the samples'
/// composition now: the tracked EMBER wordmark at the
/// top-left, the protection state at the top-right, nothing
/// else. The 2121 acceptance points below are re-pointed to
/// that contract; the goldens were regenerated and inspected
/// in the same round.
void _expectHeader(WidgetTester tester, double width, double height) {
  expect(
    find.byType(MapBrandPanel),
    findsNothing,
    reason: 'the brand panel no longer sits on the Home tab',
  );
  expect(
    find.byType(MapEngineChip),
    findsNothing,
    reason: 'the engine rail no longer sits on the Home tab',
  );
  final wordmark = find.text('EMBER');
  expect(wordmark, findsOneWidget);
  final rect = tester.getRect(wordmark);
  expect(rect.left, lessThan(24), reason: 'wordmark hugs the left edge');
  expect(rect.top, lessThan(30), reason: 'wordmark sits at the top');
  final status = find.byWidgetPredicate(
    (w) => w is Text && (w.data == 'PROTECTED' || w.data == 'NOT PROTECTED'),
  );
  expect(status, findsOneWidget);
  final statusRect = tester.getRect(status);
  expect(
    statusRect.right,
    greaterThan(width - 24),
    reason: 'protection state hugs the right edge',
  );
  expect(tester.takeException(), isNull);
}

void main() {
  setUpAll(_loadRealFonts);

  test('pubspec is 2.2.0+2126', () {
    expect(_read('pubspec.yaml'), contains('version: 2.2.0+2146'));
  });

  test('brand panel is back to the pre-2118 compact footprint', () {
    final widgets = _read('lib/ui/ember/map_widgets.dart');
    final panel = _between(
      widgets,
      'class MapBrandPanel',
      'class MapEngineChip',
    );
    expect(panel, contains('padding: const EdgeInsets.fromLTRB(9, 7, 12, 7)'));
    expect(panel, contains('width: 30'));
    // PIN UPDATED by build 2138 (visual review V-06): the
    // brand panel's 13 sp is the scale's body step now.
    expect(panel, contains('fontSize: Ember.fontBody'));
    expect(panel, isNot(contains('luminous: true')));
  });

  test('shell header: Spacer back, weighted 7:2; stretch gone', () {
    final shell = _read('lib/ui/ember/ember_shell.dart');
    final header = _between(shell, 'Widget _header()', 'Widget build(');
    expect(header, contains('flex: 7'));
    expect(header, contains('Spacer(flex: 2)'));
    expect(header, isNot(contains('SizedBox(width: 12)')));
    expect(header, contains('MapBrandPanel('));
  });

  test('engine rail order is unchanged in the header source', () {
    final shell = _read('lib/ui/ember/ember_shell.dart');
    final header = _between(shell, 'Widget _header()', 'Widget build(');
    const names = [
      'Mozilla',
      'V2Ray',
      'Psiphon',
      'Lantern',
      'OpenVPN',
      'WireGuard',
      'WARP',
      'MASQUE',
    ];
    var at = 0;
    for (final name in names) {
      final next = header.indexOf("'$name'", at);
      expect(next, isNonNegative, reason: '$name missing or out of order');
      at = next + 1;
    }
  });

  testWidgets('header at 411x915: R1 wordmark header, no rail', (
    tester,
  ) async {
    final core = await _pumpShell(tester, 411, 915);
    _expectHeader(tester, 411, 915);
    await expectLater(
      find.byType(VpnApp),
      matchesGoldenFile('screenshots/build2121-home-411.png'),
    );
    await tester.pumpWidget(const SizedBox());
    core.dispose();
  });

  testWidgets('header at 390x844: R1 wordmark header, no rail', (
    tester,
  ) async {
    final core = await _pumpShell(tester, 390, 844);
    _expectHeader(tester, 390, 844);
    await expectLater(
      find.byType(VpnApp),
      matchesGoldenFile('screenshots/build2121-home-390.png'),
    );
    await tester.pumpWidget(const SizedBox());
    core.dispose();
  });
}
